   function formatPrioritizedIssueListForEmail(
    input: PrioritizedIssueListForEmailInput
  ): FormattedIssueListForEmail {
    if (input["reportAggregationDate"] === undefined || input["reportAggregationDate"] === null) { throw new Error("reportAggregationDate is required"); }
    if (input["teamId"] === undefined || input["teamId"] === null) { throw new Error("teamId is required"); }
    const { issues, maxIssueCountInEmail } = input;
  
    if (!issues || issues.length === 0) {
      throw new EmptyIssueListError("Issue list is empty");
    }
  
    const priorityOrder: Record<string, number> = {
      high: 0,
      HIGH: 0,
      medium: 1,
      MEDIUM: 1,
      low: 2,
      LOW: 2,
    };
  
    const priorityLabelMap: Record<string, string> = {
      high: "高",
      HIGH: "高",
      medium: "中",
      MEDIUM: "中",
      low: "低",
      LOW: "低",
    };
  
    const sortedIssues = [...issues].sort((a, b) => {
      const rankA = a.priorityRank || a.priority;
      const rankB = b.priorityRank || b.priority;
  
      const orderA = priorityOrder[rankA as string] ?? 999;
      const orderB = priorityOrder[rankB as string] ?? 999;
  
      if (orderA !== orderB) {
        return orderA - orderB;
      }
  
      return (b.impactScore || 0) - (a.impactScore || 0);
    });
  
    const issuesToFormat = maxIssueCountInEmail
      ? sortedIssues.slice(0, maxIssueCountInEmail)
      : sortedIssues;
  
    let highPriorityCount = 0;
    let mediumPriorityCount = 0;
    let lowPriorityCount = 0;
  
    const htmlItems: string[] = [];
  
    for (const issue of issuesToFormat) {
      const rank = issue.priorityRank || issue.priority;
  
      if (!rank || !(rank in priorityOrder)) {
        throw new InvalidPriorityRankError(
          `Invalid priority rank value: ${rank}`
        );
      }
  
      const colorCode = issue.colorCode || issue.color;
      if (!colorCode) {
        throw new MissingColorCodeError(
          `Missing color code for issue: ${issue.issueId || issue.content}`
        );
      }
  
      const rankLower = rank.toLowerCase();
      if (rankLower === "high") {
        highPriorityCount++;
      } else if (rankLower === "medium") {
        mediumPriorityCount++;
      } else if (rankLower === "low") {
        lowPriorityCount++;
      }
  
      const issueContent = issue.content || issue.issueText || "";
      const priorityLabel = priorityLabelMap[rank] || rank;
      const frequency = issue.frequency || 0;
      const impactScore = issue.impactScore || 0;
  
      const htmlItem = `<li style="color:${colorCode}">${issueContent}（優先度: ${priorityLabel}、頻度: ${frequency}、影響度: ${impactScore}）</li>`;
      htmlItems.push(htmlItem);
    }
  
    const formattedContent = `<ul>${htmlItems.join("")}</ul>`;
  
    return {
      formattedContent,
      issueCount: issuesToFormat.length,
      highPriorityCount,
      mediumPriorityCount,
      lowPriorityCount,
    };
  }
